/* Aracne V5: durable per-trip storage and explicit lifecycle. */
'use strict';
(()=>{
 const api=window.aracneShared,clone=x=>JSON.parse(JSON.stringify(x));
 const col=Math.max(0,['fr','it','en','es'].indexOf(document.documentElement.lang));
 const words={
 hub:['Mes voyages','I miei viaggi','My trips','Mis viajes'],new:['Nouveau voyage','Nuovo viaggio','New trip','Nuevo viaje'],name:['Nom du voyage','Nome del viaggio','Trip name','Nombre del viaje'],solo:['Solo · enregistré sur cet appareil','Solo · salvato su questo dispositivo','Solo · saved on this device','Solo · guardado en este dispositivo'],shared:['Voyage partagé','Viaggio condiviso','Shared trip','Viaje compartido'],duplicate:['Dupliquer','Duplica','Duplicate','Duplicar'],remove:['Supprimer le voyage','Elimina viaggio','Delete trip','Eliminar viaje'],clear:['Vider le programme','Svuota programma','Clear plan','Vaciar programa'],clearAsk:['Effacer les étapes et leurs validations ? Le nom, les dates, les notes, les dépenses et le carnet publié sont conservés.','Cancellare tappe e convalide? Nome, date, note, spese e diario pubblicato restano.','Clear steps and validations? Name, dates, notes, expenses and published book are kept.','¿Borrar etapas y validaciones? Se conservan nombre, fechas, notas, gastos y cuaderno publicado.'],deleteAsk:['Supprimer ce voyage ? La suppression partagée concerne tout le groupe. Les exports déjà téléchargés restent.','Eliminare il viaggio? La cancellazione condivisa riguarda tutto il gruppo. Le copie scaricate restano.','Delete this trip? Shared deletion affects everyone. Downloaded exports remain.','¿Eliminar este viaje? La eliminación compartida afecta a todo el grupo. Las copias descargadas permanecen.'],empty:['Aucun voyage. Créez votre premier voyage.','Nessun viaggio. Crea il primo viaggio.','No trips. Create your first trip.','No hay viajes. Crea tu primer viaje.'],save:['Créer une sauvegarde','Crea salvataggio','Create backup','Crear copia'],restore:['Restaurer','Ripristina','Restore','Restaurar'],versions:['Sauvegardes','Salvataggi','Backups','Copias'],restoreAsk:['Restaurer cette version ? Une copie de sécurité sera conservée. Vos notes privées actuelles restent.','Ripristinare questa versione? Verrà conservata una copia di sicurezza. Le note private attuali restano.','Restore this version? A safety copy is kept. Current private notes remain.','¿Restaurar esta versión? Se conserva una copia de seguridad y tus notas privadas actuales.'],error:['Action non effectuée. Vérifiez la connexion et l’espace de stockage.','Azione non eseguita. Verifica connessione e spazio disponibile.','Action not completed. Check your connection and storage.','Acción no realizada. Comprueba conexión y almacenamiento.'],wait:['Synchronisation nécessaire : fermez les formulaires, puis réessayez.','Sincronizzazione necessaria: chiudi i moduli e riprova.','Sync required: close forms and try again.','Sincronización necesaria: cierra los formularios y reintenta.'],owner:['Action réservée à l’organisateur','Azione riservata all’organizzatore','Organiser only','Solo organizador'],saved:['Enregistré','Salvato','Saved','Guardado'],conflict:['Conflit : aucune version n’a été écrasée. Exportez votre copie avant de charger celle du groupe.','Conflitto: nessuna versione è stata sovrascritta. Esporta la tua copia prima di caricare quella del gruppo.','Conflict: neither version was overwritten. Export your copy before loading the group version.','Conflicto: ninguna versión se ha sobrescrito. Exporta tu copia antes de cargar la del grupo.'],export:['Exporter ma copie','Esporta copia','Export my copy','Exportar mi copia'],remote:['Charger la version du groupe','Carica versione del gruppo','Load group version','Cargar versión del grupo'],detach:['Conserver une copie solo indépendante ?','Conservare una copia solo indipendente?','Keep an independent solo copy?','¿Conservar una copia individual independiente?'],settings:['Voyage','Viaggio','Trip','Viaje'],help:['Aide · V5.1','Aiuto · V5.1','Help · V5.1','Ayuda · V5.1'],replay:['Revoir l’introduction','Rivedi introduzione','Replay introduction','Repetir introducción'],rename:['Renommer','Rinomina','Rename','Renombrar'],pending:['En attente de synchronisation','In attesa di sincronizzazione','Waiting to sync','Pendiente de sincronización'],configure:['Configurer le voyage','Configura viaggio','Configure trip','Configurar viaje'],expenses:['Dépenses','Spese','Expenses','Gastos'],sharing:['Partager / gérer les accès','Condividi / gestisci accessi','Share / manage access','Compartir / gestionar acceso'],leave:['Quitter ce voyage sur cet appareil','Lascia viaggio su questo dispositivo','Leave trip on this device','Salir del viaje en este dispositivo']
 };
 const t=k=>words[k]?.[col]||k,esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
 const KEY='aracne-v5-store',ACTIVE='aracne-v5-active';let store;
 try{store=JSON.parse(localStorage.getItem(KEY)||'null')}catch{store=null}
 if(!store){store={version:5,trips:{}};const legacy=localStorage.getItem('aracne-puglia-v1');if(legacy){localStorage.setItem('aracne-v4-migration-backup',JSON.stringify({state:legacy,session:localStorage.getItem('aracne-shared-v1'),library:localStorage.getItem('aracne-trip-library-v4')}));const s=api._getRaw(),id=s?.id||crypto.randomUUID();store.trips[id]={id,state:clone(state),session:s?clone(s):null,versions:[],updatedAt:new Date().toISOString()};localStorage.setItem(ACTIVE,id)}localStorage.setItem(KEY,JSON.stringify(store))}
 let active=localStorage.getItem(ACTIVE),switching=false;
 for(const entry of JSON.parse(localStorage.getItem('aracne-trip-library-v4')||'[]')){if(!store.trips[entry.id])store.trips[entry.id]={id:entry.id,name:entry.name,state:null,session:entry,versions:[],updatedAt:entry.updatedAt||''}}
 localStorage.setItem(KEY,JSON.stringify(store));
 function persist(){localStorage.setItem(KEY,JSON.stringify(store))}
 function owner(){const s=api._getRaw();return !s||s.role==='owner'}
 function checkpoint(){if(switching)return;const s=api._getRaw();let id=s?.id||active;if(!id)return;
 active=id;localStorage.setItem(ACTIVE,id);const row=store.trips[id]||{id,versions:[]};row.state=clone(state);row.session=s?clone(s):null;row.updatedAt=new Date().toISOString();store.trips[id]=row;persist();}
 const deviceKey='aracne-v5-device';if(!localStorage.getItem(deviceKey))localStorage.setItem(deviceKey,crypto.randomUUID());
 window.aracneSharedActor=()=>{const session=api._getRaw();return localStorage.getItem('aracne-collab-name-'+(session?.id||'local'))||(session?.role==='owner'?'Organisateur':'Participant')};
 const previousSave=save;save=function(){previousSave();try{checkpoint()}catch{toast(t('error'));throw Error('storage_full')}};
 window.addEventListener('aracne:shared-applied',()=>{try{checkpoint()}catch{toast(t('error'))}});
 window.addEventListener('aracne:shared-created',e=>{if(active&&active!==e.detail.id&&store.trips[active]&&!store.trips[active].session){store.trips[e.detail.id]={...store.trips[active],id:e.detail.id};delete store.trips[active];active=e.detail.id;}checkpoint()});
 window.addEventListener('pagehide',()=>{try{checkpoint()}catch{}});
 function button(id,label){return `<button class="secondary" id="${id}">${esc(t(label))}</button>`}
 function bind(id,fn){const b=document.getElementById(id);if(b)b.onclick=async()=>{b.disabled=true;try{await fn()}catch(e){toast(e.message==='sync_required'?t('wait'):t('error'))}finally{b.disabled=false}}}
 function close(){document.querySelector('#modal').close()}
 function clearAlerts(){seenEvents?.clear();document.querySelector('#v5Events')?.remove();document.querySelectorAll('.v4AlertBadge,#v4AlertAction').forEach(x=>x.remove())}
 async function activate(row){if(!row.state){const response=await api._rpc('read',{},row.session);row.state=response.document;row.session={...row.session,base:clone(response.document),revision:response.revision,role:response.role};persist()}checkpoint();switching=true;try{active=row.id;localStorage.setItem(ACTIVE,active);api._setRaw(row.session?clone(row.session):null);state=validate(clone(row.state));day=0;localStorage.setItem('aracne-puglia-v1',JSON.stringify(state));fillForm();clearAlerts();close();show(state.plan.some(d=>d.length)?'plan':'prepare');window.dispatchEvent(new CustomEvent('aracne:shared-applied'))}finally{switching=false}checkpoint();await api._tick()}
 function create(copy=false){const name=prompt(t('name'),copy?state.name:'');if(name===null||!name.trim())return;if(name.trim().length>80)throw Error('name');checkpoint();const id=crypto.randomUUID(),doc=copy?clone(state):defaults();doc.name=name.trim();doc.frameworkLocked=copy?Boolean(doc.frameworkLocked):false;doc.localTripId=id;doc.journal=copy?doc.journal||[]:[];const row={id,state:doc,session:null,versions:[],updatedAt:new Date().toISOString()};store.trips[id]=row;persist();activate(row)}
 async function settled(){if(api._busy())throw Error('sync_required');if(api._getRaw()){await api._tick();if(api._busy()||api._pending()||['offline','conflict','denied','newer'].includes(api._status()))throw Error('sync_required')}checkpoint()}
 function openTrips(){checkpoint();const rows=Object.values(store.trips).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));dialog(t('hub'),`<p class="small">V5 · ${esc(t('solo'))}</p>${button('v5New','new')}<div class="v5Trips">${rows.map(r=>`<button class="secondary" data-v5-trip="${esc(r.id)}"><b>${esc(r.state?.name||r.name||t('shared'))}</b><small>${esc(r.session?t('shared')+' · '+r.session.role:t('solo'))}</small></button>`).join('')||`<p>${esc(t('empty'))}</p>`}</div>`);bind('v5New',()=>create());document.querySelectorAll('[data-v5-trip]').forEach(b=>b.onclick=()=>{try{activate(store.trips[b.dataset.v5Trip]).catch(()=>toast(t('error')))}catch{toast(t('error'))}})}
 async function clearPlan(){if(!owner()){toast(t('owner'));return}if(!confirm(t('clearAsk')))return;await settled();saveVersionLocal('Before clearing');state.plan=[];state.frameworkLocked=false;state.resetEpoch=crypto.randomUUID();save();fillForm();close();show('prepare')}
 function saveVersionLocal(label){checkpoint();const row=store.trips[active];if(!row)return;row.versions.push({id:crypto.randomUUID(),label,at:new Date().toISOString(),state:clone(state)});persist()}
 async function backup(){const name=prompt(t('save'),'');if(name===null)return;await settled();if(api._getRaw()){if(!owner())throw Error('owner');await api._rpc('snapshot',{p_label:name,p_actor:window.aracneSharedActor?.()})}saveVersionLocal(name);toast(t('saved'))}
 async function versions(){if(api._getRaw()){const r=await api._rpc('versions');dialog(t('versions'),r.versions.map(v=>`<p>${esc(v.label||v.name)} · ${esc(v.created_at)} ${owner()?`<button class="secondary" data-v5-server-version="${Number(v.id)}">${esc(t('restore'))}</button>`:''}</p>`).join(''));document.querySelectorAll('[data-v5-server-version]').forEach(b=>b.onclick=async()=>{try{if(!confirm(t('restoreAsk')))return;await settled();await api._rpc('snapshot',{p_label:'Before restore'});saveVersionLocal('Before restore');const current=api._getRaw(),r=await api._rpc('restore',{p_version_id:Number(b.dataset.v5ServerVersion)});if(api._getRaw()!==current)return;api._setRaw({...current,base:clone(r.document),revision:r.revision,name:r.name});api._apply(r.document);checkpoint();close()}catch{toast(t('error'))}});return}
 const rows=store.trips[active]?.versions||[];dialog(t('versions'),rows.map(v=>`<p>${esc(v.label||v.at)} ${button('v5Restore'+v.id,'restore')}</p>`).join('')||esc(t('empty')));for(const v of rows)bind('v5Restore'+v.id,()=>{if(!confirm(t('restoreAsk')))return;const privateNotes=state.notes.filter(n=>n.privacy==='private');saveVersionLocal('Before restore');state=clone(v.state);state.notes=[...state.notes.filter(n=>n.privacy==='group'),...privateNotes.map(n=>({...n,day:n.day>=state.days?-1:n.day}))];save();fillForm();close();show('plan')})}
 async function remove(){if(!owner()){toast(t('owner'));return}if(!confirm(t('deleteAsk')+'\n'+state.name))return;if(api._busy())throw Error('sync_required');const id=active,s=api._getRaw();if(s)await api._rpc('delete');delete store.trips[id];persist();const rows=JSON.parse(localStorage.getItem('aracne-trip-library-v4')||'[]');localStorage.setItem('aracne-trip-library-v4',JSON.stringify(rows.filter(r=>r.id!==id)));switching=true;api._setRaw(null);active=null;localStorage.removeItem(ACTIVE);localStorage.removeItem('aracne-puglia-v1');state=defaults();state.name='';state.plan=[];fillForm();switching=false;close();show('prepare');openTrips()}
 function detach(){if(!confirm(t('detach')))return;checkpoint();const name=state.name,id=crypto.randomUUID(),row={id,state:clone(state),session:null,versions:[],updatedAt:new Date().toISOString()};row.state.localTripId=id;row.state.name=name;store.trips[id]=row;persist();activate(row)}
 async function rename(){if(!owner()){toast(t('owner'));return}const name=prompt(t('name'),state.name);if(name===null||!name.trim())return;if(name.trim().length>80)throw Error('name');await settled();state.name=name.trim();save();fillForm();if(view==='plan')renderPlan();openHub()}
 
 function openHub(){checkpoint();dialog(t('settings'),`<h3>${esc(state.name)}</h3><p>${esc(api._getRaw()?t('shared')+' · '+api._getRaw().role:t('solo'))}</p><div class="v5Actions">${button('v5Trips','hub')}${button('v5New','new')}${button('v5Duplicate','duplicate')}${button('v5Configure','configure')}${button('v5Expenses','expenses')}${button('v5Share','sharing')}${owner()?button('v5Rename','rename')+button('v5Backup','save'):''}${button('v5Versions','versions')}${owner()?button('v5Clear','clear')+button('v5Delete','remove'):button('v5Leave','leave')}</div>`);bind('v5Trips',openTrips);bind('v5New',()=>create());bind('v5Duplicate',()=>create(true));bind('v5Configure',()=>{close();show('prepare')});bind('v5Expenses',()=>{close();show('budget')});bind('v5Share',()=>shareDialog());bind('v5Rename',rename);bind('v5Backup',backup);bind('v5Versions',versions);bind('v5Clear',clearPlan);bind('v5Delete',remove);bind('v5Leave',detach)}
 api.open=openHub;document.querySelector('#tripMenu').onclick=openHub;document.querySelector('.v4TripsShortcut')?.remove();const shortcut=document.createElement('button');shortcut.className='secondary';shortcut.textContent=t('hub');shortcut.onclick=openTrips;document.querySelector('.sharedBar').append(shortcut);
 const help=[
 ['Solo ou à plusieurs','Solo o insieme','Solo or together','Solo o en grupo'],
 ['Créez et nommez un voyage dans Mes voyages. En solo, les données restent sur cet appareil : exportez une copie pour les conserver ailleurs. Touchez Inviter, choisissez « Peut lire et modifier » ou « Lecture seule », puis WhatsApp dans le partage du téléphone. Le nom du voyage actif reste affiché en haut.','Crea e nomina un viaggio in I miei viaggi. In solo, i dati restano sul dispositivo: esporta una copia per conservarli altrove. Tocca Invita, scegli « Può leggere e modificare » o « Sola lettura », poi WhatsApp nel menu del telefono. Il nome del viaggio attivo resta in alto.','Create and name a trip in My trips. Solo data stays on this device: export a copy to keep it elsewhere. Tap Invite, choose « Can view and edit » or « View only », then WhatsApp in the phone share sheet. The active trip name stays at the top.','Crea y nombra un viaje en Mis viajes. Los datos individuales permanecen en este dispositivo: exporta una copia para guardarlos fuera. Toca Invitar, elige « Puede leer y modificar » o « Solo lectura », y WhatsApp en el menú del teléfono. El nombre del viaje activo permanece arriba.'],
 ['Programme · Journal · Carnet','Programma · Diario · Taccuino','Programme · Activity · Travel book','Programa · Diario · Cuaderno'],
 ['Programme : préparez les étapes. Journal : consultez les actions. Carnet : retrouvez la dernière version publiée. La Carte est en haut ; les Dépenses et Mes voyages sont dans Options.','Programma: prepara le tappe. Diario: consulta le azioni. Taccuino: ritrova l’ultima versione pubblicata. La Mappa è in alto; Spese e I miei viaggi sono in Opzioni.','Programme: edit steps. Activity: review actions. Travel book: view the last published version. Map is at the top; Expenses and My trips are in Options.','Programa: prepara etapas. Diario: consulta acciones. Cuaderno: última versión publicada. El Mapa está arriba; Gastos y Mis viajes están en Opciones.'],
 ['Rôles et synchronisation','Ruoli e sincronizzazione','Roles and sync','Roles y sincronización'],
 ['Les participants modifient le programme commun ; l’organisateur valide et publie. Un lecteur consulte seulement. Hors ligne, les changements restent en attente. Un conflit nécessite une décision : exportez votre copie avant de charger celle du groupe.','I partecipanti modificano il programma comune; l’organizzatore convalida e pubblica. Il lettore consulta. Offline le modifiche restano in attesa. Un conflitto richiede una decisione: esporta la tua copia prima di caricare quella del gruppo.','Participants edit the common programme; the organiser validates and publishes. Viewers only read. Offline changes wait for connection. A conflict needs a decision: export your copy before loading the group version.','Los participantes editan el programa común; el organizador valida y publica. Los lectores consultan. Sin conexión los cambios esperan. Un conflicto requiere decidir: exporta tu copia antes de cargar la del grupo.'],
 ['Sauvegardes et suppression','Salvataggi ed eliminazione','Backups and deletion','Copias y eliminación'],
 ['Vider le programme conserve le voyage, les notes et les dépenses. Supprimer retire le voyage ; les exports restent. Restaurer une version commune conserve vos notes privées actuelles. Les liens donnent un accès : gardez le lien administrateur privé.','Svuotare il programma conserva viaggio, note e spese. Eliminare rimuove il viaggio; le esportazioni restano. Ripristinare una versione condivisa conserva le note private attuali. I link danno accesso: conserva il link amministratore privato.','Clearing the plan keeps the trip, notes and expenses. Deleting removes the trip; exports remain. Restoring a shared version keeps current private notes. Links grant access: keep the administrator link private.','Vaciar el programa conserva viaje, notas y gastos. Eliminar retira el viaje; las exportaciones permanecen. Restaurar una versión compartida conserva tus notas privadas actuales. Los enlaces dan acceso: guarda el de administrador en privado.']
 ];
 window.aracneHelp=()=>{dialog(t('help'),help.map((a,i)=>i%2?`<p>${esc(a[col])}</p>`:`<h3>${esc(a[col])}</h3>`).join('')+button('v5Replay','replay')+button('v5Export','export'));bind('v5Replay',()=>{close();window.aracneIntro.open()});bind('v5Export',()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'aracne-voyage.json'))};
 document.querySelector('#helpButton').onclick=window.aracneHelp;
 window.addEventListener('aracne:sync-status',e=>{let b=document.querySelector('#v5Conflict');if(e.detail.status==='conflict'){if(!b){b=document.createElement('button');b.id='v5Conflict';b.className='secondary';b.textContent=t('conflict');document.querySelector('.sharedBar').append(b);b.onclick=()=>{dialog(t('conflict'),button('v5ExportConflict','export')+button('v5Remote','remote'));bind('v5ExportConflict',()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'aracne-conflit.json'));bind('v5Remote',async()=>{saveVersionLocal('Conflict');await api._resolve();checkpoint();close()})}}}else b?.remove()});
 
 function denyRead(e){if(api._getRaw()?.role!=='read')return;const el=e.target;if(el.closest('#itinerary button,#expenseForm button,#saveMembers,[data-delete-exp],#addStep,#finalizePlan')||(e.type==='submit'&&el.matches('#tripForm,#stepForm,#expenseForm'))){e.preventDefault();e.stopImmediatePropagation();toast(t('owner'))}}
 document.addEventListener('click',denyRead,true);document.addEventListener('submit',denyRead,true);
 let seenEvents=new Set();window.aracneSharedV4Events=events=>{const fresh=events.filter(e=>!seenEvents.has(e.id));fresh.forEach(e=>seenEvents.add(e.id));if(!fresh.length)return;const btn=document.querySelector('nav [data-view="journal"]');let badge=document.querySelector('#v5Events');if(!badge){badge=document.createElement('span');badge.id='v5Events';btn?.append(badge)}badge.textContent=' · '+fresh.length;};
 document.querySelector('nav')?.addEventListener('click',e=>{if(e.target.closest('[data-view="journal"]'))document.querySelector('#v5Events')?.remove()});

 function registerShared(sourceId,session,doc){const prior=store.trips[sourceId];store.trips[session.id]={...(prior||{versions:[]}),id:session.id,state:prior?.state||clone(doc),session:clone(session),updatedAt:new Date().toISOString()};if(prior)delete store.trips[sourceId];persist()}
 window.aracneV5={registerShared,checkpoint,openTrips,openHub,create,remove,clearPlan,detach,settled,versions,store:()=>clone(store)};
 if(active&&store.trips[active]&&!api._getRaw()){state=validate(clone(store.trips[active].state));fillForm()}
 if(!active&&!api._getRaw()&&!location.hash.includes('trip=')){state.name='';fillForm();setTimeout(()=>{if(!document.querySelector('#welcome').open)openTrips();else document.querySelector('#welcome').addEventListener('close',openTrips,{once:true})},200)}
})();
